window.POETRY_REGISTER("v5-strict-8-12-0-97d2774eb32e.js",{"poems":[[47435,2],[57946,2],[58198,2],[165685,7],[187764,7],[191615,7],[234162,7],[271998,7],[272018,7],[272193,7],[286732,7],[288139,7],[358684,9],[359267,9],[364419,9],[650074,5]],"pairs":[["如夔如龙羞如龚黄","吾不知此之言兮是何之言兮",0],["晋岭汾川非南朝地","而晋山汾水广见于唐代诗文",1],["惟据连枝台座之语","知尹河南者为时相之昆弟耳",2],["金陵朱世英官长沙","或有画箕踞而坐者号大着肚",3],["唐虞不作兮汤武非","来者不可见兮而往者不可追",4],["只将破草鞵泥弹子","向十字街头换得眼睛三百担",5],["堇不苦兮将辞其实","难倍伊蓰周兮又奚著而奚作",6],["因私淑以儆诸后学","又有以见前辈用心之不颇也",7],["使其不为三子之累","则后日之笔当不至于轻掷也",8],["鸡鸣喈喈兮霜月晓","纷纭归梦兮殷辘轳之下银床",9],["湘之岳兮帝宫谒帝","帝不敢骄兮奔魑魅而走蜚龙",10],["迹虽疏兮此心不忘","死生契阔兮怅十二里之高冈",11],["我思古人兮李太白","孰为使之朝禁林而暮采石也",12],["曲再弹兮天地为秋","归来兮清都之上不可以久留",13],["吾君吾王兮寿万岁","得与秋香月色兮酬酹乎樽觞",14],["乌江逼死他盟兄弟","就是那座下的乌骓也解哀号",15],["他爹娘受罪全不管","干操心的忠臣呕血蛊了疮疤",15]]});
